/* zqsort<Particle::BufferElement*> 0x2360a0 (the only instance in the ELF; no skeleton entry):
   an iterative quicksort - median of three (lo, mid, hi ordered), partition around the middle
   value, the smaller part handled first with the larger pushed on a local stack of {lo, hi}
   pairs - that leaves runs of up to 9 entries, then one insertion sort over the whole array.
   cmp < 0 orders a before b. ELF quirk kept: the stack (151 pairs) is not bounds-checked. */
template <class T>
void zqsort(T* a, int n, int (*cmp)(const T&, const T&))
{
	struct { int lo, hi; } stack[151];
	int sp = 0;
	int lo = 0;
	int hi = n - 1;

	for (;;)
	{
		if (lo + 8 < hi)
		{
			int sum = lo + hi;
			T* first = &a[lo];
			T* mid = &a[sum >> 1];
			T* last = &a[hi];
			T tmp;

			if (cmp(*first, *mid) > 0) { tmp = *first; *first = *mid; *mid = tmp; }
			if (cmp(*first, *last) > 0) { tmp = *first; *first = *last; *last = tmp; }
			if (cmp(*mid, *last) > 0) { tmp = *mid; *mid = *last; *last = tmp; }

			T pivot = *mid;
			int i = lo + 1;
			int j = hi - 1;

			do
			{
				while (cmp(a[i], pivot) < 0)
					i++;

				while (cmp(a[j], pivot) > 0)
					j--;

				if (j < i)
					break;

				tmp = a[i];
				a[i] = a[j];
				a[j] = tmp;
				i++;
				j--;
			} while (!(j < i));

			if (sum < i + j)
			{
				/* the right part [i, hi] is the smaller: push the left one */
				stack[sp].lo = lo;
				stack[sp].hi = j;
				lo = i;
			}
			else
			{
				stack[sp].lo = i;
				stack[sp].hi = hi;
				hi = j;
			}

			sp++;
		}
		else if (sp > 0)
		{
			sp--;
			hi = stack[sp].hi;
			lo = stack[sp].lo;
		}
		else
			break;
	}

	for (int i = 1; i < n; i++)
	{
		T tmp = a[i];
		int j = i;

		while (cmp(a[j - 1], tmp) > 0)
		{
			a[j] = a[j - 1];

			if (--j == 0)
				break;
		}

		a[j] = tmp;
	}
}

/* bufferPtrCompare__8ParticleFRCPQ28Particle13BufferElementRCPQ28Particle13BufferElement
   0x234680 (no skeleton entry). ELF quirk kept: it returns the bits of the float difference
   a - b as the int (so -0.0 compares as negative). */
int Particle::bufferPtrCompare(Particle::BufferElement* const& a, Particle::BufferElement* const& b)
{
	f32 diff = a->m_depth - b->m_depth;
	int bits;

	memcpy(&bits, &diff, sizeof(bits));
	return bits;
}

/* ELF quirk kept: the draw loops stop on a NULL entry *pParticleBuf, and DrawPrep / DrawOne /
   DrawRange step the cursor one below bufferPtr[0] without a bound check. In the ELF that
   word is the last word of buffer (0x4d96e0 + 160000 = bufferPtr 0x5007e0): element 4999's
   depth, zero (NULL, range -1) until all 5000 elements are used. port: GCC does not keep the
   two arrays adjacent, so the cursor's entry is read through this helper. */
static Particle::BufferElement* CursorEntry(Particle::BufferElement** cursor)
{
	if (cursor < Particle::bufferPtr)
	{
		Particle::BufferElement* last;
		memcpy(&last, &Particle::buffer[4999].m_depth, sizeof(last));
		return last;
	}

	return *cursor;
}

/* the cursor element's depth squared, or -1 past the sorted entries */
static f32 CursorRange()
{
	Particle::BufferElement* element = CursorEntry(Particle::pParticleBuf);

	if (element == NULL)
		return -1.0f;

	return element->m_depth * element->m_depth;
}

/* draw the cursor element by its source's draw type (the switch inlined in DrawRange, DrawOne
   and DrawFlush) with the camera's world-to-screen matrix (VU frame setup, VU 4-7) */
static void DrawCursorElement()
{
	Particle::BufferElement* element = CursorEntry(Particle::pParticleBuf);
	f32 (&matrix)[4][4] = thePipe.m_camera->m_mtxSet.m_vu->mtxWorldToScreen;

	switch (element->m_instance->m_source->m_drawType)
	{
	case PARTICLE_STANDARD:
		element->Draw(matrix);
		break;
	case PARTICLE_ROTATED:
		element->DrawRotated(matrix);
		break;
	case PARTICLE_XZ:
		element->DrawXZ(matrix);
		break;
	case PARTICLE_STREAKED:
		element->DrawStreaked(matrix);
		break;
	default:
		break;
	}
}

/* point bufferPtr[i] at buffer[i] for the queued particles and sort them nearest first (the
   loop inlined at the top of DrawPrep 0x235f50 and Draw 0x234530) */
static void SortBuffer()
{
	Particle::Source::RenderBBox();

	for (s32 i = 0; i < Particle::numParticles; i++)
		Particle::bufferPtr[i] = &Particle::buffer[i];

	zqsort(Particle::bufferPtr, Particle::numParticles, Particle::bufferPtrCompare);
	Particle::pParticleBuf = &Particle::bufferPtr[Particle::numParticles - 1];
}

/* @socom-skeleton stub DrawPrep__8ParticleFv */
float Particle::DrawPrep()
{
	/* 0x235f50: sort the queued particles; the cursor starts at the farthest one, and the
	   result is its depth squared (or -1 when there is none) */
	SortBuffer();
	return CursorRange();
}

/* port: file-local helpers, not ELF functions - DrawRotated, DrawXZ and DrawStreaked write
   this inline: the texture's DMA REF when it changes, then (CNT tag / VIF FLUSH + DIRECT) a
   GIF tag NLOOP 6, EOP, PRE, PRIM TRIANGLE | TME | ABE, PACKED ST RGBAQ XYZ2, and six
   vertices (two triangles 0-2-3 and 0-1-2 of a quad), ST (0 or q, 0 or q, q) with
   q = 1 / z; kicked with CSPR::Kick. */
static _word128* QuadPacketStart(zdb::CTexture* texture)
{
	_word128* cnt = reinterpret_cast<_word128*>(Particle::BufferElement::m_spr);

	if (reinterpret_cast<s32>(texture) != Particle::m_lastTexture)
	{
		Particle::m_lastTexture = reinterpret_cast<s32>(texture);
		*cnt = texture->m_dmaRef;
		cnt++;
	}

	_word128* p = cnt + 1;
	p->u64[0] = 0x3029c00000008006ull;
	p->u64[1] = 0x512;
	Particle::BufferElement::m_spr = reinterpret_cast<s32>(p + 1);
	return cnt;
}

static void QuadPacketVertex(f32 s, f32 t, f32 q, const CPnt4D* colour, s32 x, s32 y, s32 z)
{
	_word128* p = reinterpret_cast<_word128*>(Particle::BufferElement::m_spr);
	p[0].f32[0] = s;
	p[0].f32[1] = t;
	p[0].f32[2] = q;
	p[0].u32[3] = 0;
	sceVu0FTOI0Vector(reinterpret_cast<s32*>(p[1].u32), reinterpret_cast<f32*>(const_cast<CPnt4D*>(colour)));
	p[2].u32[0] = x;
	p[2].u32[1] = y;
	p[2].u32[2] = z;
	p[2].u32[3] = 0;
	Particle::BufferElement::m_spr = reinterpret_cast<s32>(p + 3);
}

static void QuadPacketEnd(_word128* cnt)
{
	_word128* p = reinterpret_cast<_word128*>(Particle::BufferElement::m_spr);
	u32 qwc = (u32)(p - cnt) - 1;
	cnt->u32[0] = qwc | 0x10000000; /* DMAtag CNT */
	cnt->u32[1] = 0;
	cnt->u32[2] = 0x11000000;       /* VIF FLUSH */
	cnt->u32[3] = qwc | 0x50000000; /* VIF DIRECT */
	CSPR::Kick(p, false);
}

/* @socom-skeleton stub DrawStreaked__Q28Particle13BufferElementFRA4_A4_f */
void Particle::BufferElement::DrawStreaked(float (&matrix)[4][4])
{
	/* 0x235780: a quad from the instance's last position (tail: the colour with alpha times
	 * the source's streak fade) to its position (head), half width the projected size
	 * (256 m_size / w, w of the head, times the view-to-screen x scale), across the screen
	 * direction; the head goes out by that size along it, the tail back by streak length
	 * times it. Not drawn for an unmoved instance, nearer than z 500, reaching the screen
	 * edge (0 .. 0x10000), or untextured. ELF quirks kept: both ends take the tail's z and the
	 * XYZ z written is 1.5 times it (q = 1 / that); a zero screen direction is (dx, -1); the
	 * edge tests use the signed offsets. */
	_word128* start = reinterpret_cast<_word128*>(zSysSprGetPacket(reinterpret_cast<unsigned __int128**>(&CSPR::m_sprPacketEnd)));
	CSPR::m_sprPacket = start;
	m_spr = reinterpret_cast<s32>(start);
	Instance* inst = m_instance;

	if (inst->m_pos.x == inst->m_prev.x && inst->m_pos.y == inst->m_prev.y && inst->m_pos.z == inst->m_prev.z)
		return;

	CPnt4D tail = m_color;
	tail.w *= inst->m_source->m_streakFade;

	f32 at[4] = { inst->m_pos.x, inst->m_pos.y, inst->m_pos.z, 1.0f };
	s32 head[4];
	sceVu0RotTransPers(head, matrix, at, 0);
	head[2] >>= 4;
	at[0] = inst->m_prev.x;
	at[1] = inst->m_prev.y;
	at[2] = inst->m_prev.z;
	s32 back[4];
	sceVu0RotTransPers(back, matrix, at, 0);
	back[2] >>= 4;

	f32 size = ((256.0f * m_size) / (f32)head[3]) * thePipe.m_camera->m_mtxSet.mtxViewToScreen[0][0];
	f32 dx = (f32)(head[0] - back[0]);
	f32 dy = (f32)(head[1] - back[1]);
	f32 len2 = dx * dx + dy * dy;

	if (len2 < 1e-05f)
		dy = -1.0f;
	else
	{
		f32 inv = 1.0f / sqrtf(len2);
		dx *= inv;
		dy *= inv;
	}

	f32 streak = inst->m_source->m_streakLen;
	head[0] = (s32)((f32)head[0] + dx * size);
	head[1] = (s32)((f32)head[1] + dy * size);
	streak *= size;
	back[0] = (s32)((f32)back[0] - dx * streak);
	back[1] = (s32)((f32)back[1] - dy * streak);
	s32 ox = (s32)(size * dy);
	s32 oy = (s32)(-size * dx);
	s32 zb = back[2];
	head[2] = zb;
	s32 z = (s32)((f32)zb + 0.5f * (f32)zb);

	if (zb < 500 || head[2] < 500)
		return;

	if (back[0] < head[0])
	{
		if (back[0] - ox <= 0 || !(head[0] + ox < 0x10000))
			return;
	}
	else if (head[0] - ox <= 0 || !(back[0] + ox < 0x10000))
		return;

	if (back[1] < head[1])
	{
		if (back[1] - oy <= 0 || !(head[1] + oy < 0x10000))
			return;
	}
	else if (head[1] - oy <= 0 || !(back[1] + oy < 0x10000))
		return;

	if (m_texture == NULL)
		return;

	_word128* cnt = QuadPacketStart(m_texture);
	f32 q = 1.0f / (f32)z;
	QuadPacketVertex(0.0f, 0.0f, q, &tail, back[0] - ox, back[1] - oy, z);
	QuadPacketVertex(q, q, q, &m_color, head[0] + ox, head[1] + oy, z);
	QuadPacketVertex(q, 0.0f, q, &tail, back[0] + ox, back[1] + oy, z);
	QuadPacketVertex(0.0f, 0.0f, q, &tail, back[0] - ox, back[1] - oy, z);
	QuadPacketVertex(0.0f, q, q, &m_color, head[0] - ox, head[1] - oy, z);
	QuadPacketVertex(q, q, q, &m_color, head[0] + ox, head[1] + oy, z);
	QuadPacketEnd(cnt);
}

/* @socom-skeleton stub DrawXZ__Q28Particle13BufferElementFRA4_A4_f */
void Particle::BufferElement::DrawXZ(float (&matrix)[4][4])
{
	/* 0x235260: a quad lying in the world's xz plane: the corners are the projected centre
	 * plus and minus the projected size (256 m_size / w times the view-to-screen x scale)
	 * along the world-to-view matrix's x and z rows (x, y components). Not drawn nearer than
	 * z 10, with the centre off 0 .. 0x10000, or untextured. */
	_word128* start = reinterpret_cast<_word128*>(zSysSprGetPacket(reinterpret_cast<unsigned __int128**>(&CSPR::m_sprPacketEnd)));
	CSPR::m_sprPacket = start;
	m_spr = reinterpret_cast<s32>(start);
	f32 at[4] = { m_instance->m_pos.x, m_instance->m_pos.y, m_instance->m_pos.z, 1.0f };
	s32 screen[4];
	sceVu0RotTransPers(screen, matrix, at, 0);
	screen[2] >>= 4;
	zdb::tag_ZCAM_MTX_SET* set = &thePipe.m_camera->m_mtxSet;
	f32 f = ((256.0f * m_size) / (f32)screen[3]) * set->mtxViewToScreen[0][0];
	f32 ax = set->mtxWorldToView[0][0] * f;
	f32 ay = set->mtxWorldToView[0][1] * f;
	f32 bx = set->mtxWorldToView[2][0] * f;
	f32 by = set->mtxWorldToView[2][1] * f;
	s32 x = screen[0];
	s32 y = screen[1];
	s32 z = screen[2];
	f32 x0 = (f32)x - ax;
	f32 y0 = (f32)y - ay;
	f32 x1 = (f32)x + ax;
	f32 y1 = (f32)y + ay;
	s32 c[4][2];
	c[0][0] = (s32)(x0 - bx);
	c[0][1] = (s32)(y0 - by);
	c[1][0] = (s32)(x1 - bx);
	c[1][1] = (s32)(y1 - by);
	c[2][0] = (s32)(bx + x1);
	c[2][1] = (s32)(by + y1);
	c[3][0] = (s32)(bx + x0);
	c[3][1] = (s32)(by + y0);

	if (z < 10 || x < 0 || !(x < 0x10001) || y < 0 || !(y < 0x10001) || m_texture == NULL)
		return;

	_word128* cnt = QuadPacketStart(m_texture);
	f32 q = 1.0f / (f32)z;
	QuadPacketVertex(0.0f, 0.0f, q, &m_color, c[0][0], c[0][1], z);
	QuadPacketVertex(q, q, q, &m_color, c[2][0], c[2][1], z);
	QuadPacketVertex(q, 0.0f, q, &m_color, c[3][0], c[3][1], z);
	QuadPacketVertex(0.0f, 0.0f, q, &m_color, c[0][0], c[0][1], z);
	QuadPacketVertex(0.0f, q, q, &m_color, c[1][0], c[1][1], z);
	QuadPacketVertex(q, q, q, &m_color, c[2][0], c[2][1], z);
	QuadPacketEnd(cnt);
}

