	f32 fb = (f32)b * 1.0f;
	s32 c0x = (s32)((f32)x + fa), c0y = (s32)((f32)y + fb);
	s32 c1x = (s32)((f32)x - fb), c1y = (s32)((f32)y + fa);
	s32 c2x = (s32)((f32)x - fa), c2y = (s32)((f32)y - fb);
	s32 c3x = (s32)((f32)x + fb), c3y = (s32)((f32)y - fa);

